ak0(a){return"\u0421\u0440\u043e\u043a \u0432\u044b\u0448\u0435\u043b "+a+" \u2014 \u0448\u0442\u0440\u0430\u0444 \u0432\u044b\u043f\u0438\u0441\u0430\u043d"},
ajU(a,b){return"\u041f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043d\u0430 \u0443\u0447\u0451\u0442 \u0434\u043e "+a+" (\u043e\u0441\u0442\u0430\u043b\u043e\u0441\u044c "+b+")"},
ajD(a){var s=""+a,r=s+" \u0434\u043d\u044f"
return A.cm(a,r,this.a,s+" \u0434\u043d\u0435\u0439",s+" \u0434\u0435\u043d\u044c",r,null,null)},
gajT(){return"\u2705 \u041c\u0430\u0448\u0438\u043d\u0430 \u043d\u0430 \u0443\u0447\u0451\u0442\u0435 \u2014 \u043d\u043e\u0432\u043e\u0435 \u0421\u0422\u0421 \u0432\u044b\u0434\u0430\u043d\u043e"},
gajR(){return"\u041c\u0430\u0448\u0438\u043d\u0430 \u0443\u0436\u0435 \u043d\u0430 \u0443\u0447\u0451\u0442\u0435"},
gak_(){return"\ud83d\udccd \u041e\u0441\u043c\u043e\u0442\u0440 \u2014 \u0432 \u0413\u0418\u0411\u0414\u0414 \u0433\u043e\u0440\u043e\u0434\u0430, \u0433\u0434\u0435 \u0441\u0442\u043e\u0438\u0442 \u043c\u0430\u0448\u0438\u043d\u0430"},
gajW(){return"\ud83d\ude9a \u041c\u0430\u0448\u0438\u043d\u0430 \u0432 \u043f\u0443\u0442\u0438 \u2014 \u0434\u043e\u0436\u0434\u0438\u0442\u0435\u0441\u044c \u0435\u0451"},
gajZ(){return"\u274c \u041d\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u0434\u0435\u043d\u0435\u0433 \u043d\u0430 \u0433\u043e\u0441\u043f\u043e\u0448\u043b\u0438\u043d\u0443"},
gajS(){return"\u26d4 \u041e\u0442\u043a\u0430\u0437: \u043d\u0430 \u043c\u0430\u0448\u0438\u043d\u0435 \u0437\u0430\u043f\u0440\u0435\u0442 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0445 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439. \u0413\u043e\u0441\u043f\u043e\u0448\u043b\u0438\u043d\u0430 \u043d\u0435 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f"},
gak1(){return"\u26d4 \u041e\u0442\u043a\u0430\u0437: VIN \u043d\u0435 \u0441\u043e\u0432\u043f\u0430\u043b \u0441 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u043c\u0438. \u0413\u043e\u0441\u043f\u043e\u0448\u043b\u0438\u043d\u0430 \u043d\u0435 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f"},
